**server.js**
```js
const express = require('express');

const app = express();
const port = process.env.PORT || 3000;

app.get('/time', (req, res) => {
  const now = new Date();
  res.json({
    iso: now.toISOString(),
    unix: Math.floor(now.getTime() / 1000),
    local: now.toString(),
  });
});

app.listen(port, () => {
  console.log(`Time server listening on http://localhost:${port}/time`);
});
```

